/bin/zsh -lc "nl -ba analysis.py | sed -n '1,180p'; python -c \"import pandas as pd, numpy as np; from analysis import fit_wealth_quantile; d=pd.read_csv('data/nls_incarceration_processed.csv');
for q in (.1,.5,.9):
 r=fit_wealth_quantile(d,q); b=np.array(list(r['coef'].values()),dtype=float); X=np.column_stack((np.ones(len(d)),d.race.eq('black'),d.race.eq('hipanic'),d.sex.eq('male'),d.ever_jailed)); u=d.composite_wealth_1996.to_numpy(float)-X@b; loss=np.sum(np.where(u>=0,q*u,(q-1)*u)); print(q, 'loss=',loss, 'max_eq_resid=',np.max(np.abs(X@b+np.maximum(u,0)-np.maximum(-u,0)-d.composite_wealth_1996.to_numpy(float))), 'n_negative=',(u<0).sum(), 'n_positive=',(u>0).sum())\""

